    20→)
    21→
    22→var (
    23→	// GossipDataColumnSidecarRequirements defines the set of requirements that DataColumnSidecars received on gossip
    24→	// must satisfy in order to upgrade an RODataColumn to a VerifiedRODataColumn.
    25→	// https://github.com/ethereum/consensus-specs/blob/master/specs/fulu/p2p-interface.md#data_column_sidecar_subnet_id
    26→	GossipDataColumnSidecarRequirements = []Requirement{
    27→		RequireValidFields,
    28→		RequireCorrectSubnet,
    29→		RequireNotFromFutureSlot,
    30→		RequireSlotAboveFinalized,
    31→		RequireValidProposerSignature,
    32→		RequireSidecarParentSeen,
    33→		RequireSidecarParentValid,
    34→		RequireSidecarParentSlotLower,
    35→		RequireSidecarDescendsFromFinalized,
    36→		RequireSidecarInclusionProven,
    37→		RequireSidecarKzgProofVerified,
    38→		RequireSidecarProposerExpected,
    39→	}
    40→
    41→	// ByRangeRequestDataColumnSidecarRequirements defines the set of requirements that DataColumnSidecars received
    42→	// via the by range request must satisfy in order to upgrade an RODataColumn to a VerifiedRODataColumn.
    43→	// https://github.com/ethereum/consensus-specs/blob/master/specs/fulu/p2p-interface.md#datacolumnsidecarsbyrange-v1
    44→	ByRangeRequestDataColumnSidecarRequirements = []Requirement{
    45→		RequireValidFields,
    46→		RequireSidecarInclusionProven,
    47→		RequireSidecarKzgProofVerified,
    48→	}
    49→
    50→	// ByRootRequestDataColumnSidecarRequirements defines the set of requirements that DataColumnSidecars received
    51→	// via the by root request must satisfy in order to upgrade an RODataColumn to a VerifiedRODataColumn.
    52→	// https://github.com/ethereum/consensus-specs/blob/master/specs/fulu/p2p-interface.md#datacolumnsidecarsbyroot-v1
    53→	ByRootRequestDataColumnSidecarRequirements = []Requirement{
    54→		RequireValidFields,
    55→		RequireSidecarInclusionProven,
    56→		RequireSidecarKzgProofVerified,
    57→	}
    58→
    59→	// SpectestDataColumnSidecarRequirements is used by the forkchoice spectests when verifying data columns used in the on_block tests.
    60→	SpectestDataColumnSidecarRequirements = requirementList(GossipDataColumnSidecarRequirements).excluding(
    61→		RequireSidecarParentSeen, RequireSidecarParentValid)
    62→
    63→	errColumnsInvalid = errors.New("data columns failed verification")
    64→	errBadTopicLength = errors.New("topic length is invalid")
    65→	errBadTopic       = errors.New("topic is not of the one expected")
    66→)
    67→
    68→type (
    69→	RODataColumnsVerifier struct {
    70→		*sharedResources
    71→		results                     *results
    72→		dataColumns                 []blocks.RODataColumn
    73→		verifyDataColumnsCommitment rodataColumnsCommitmentVerifier
    74→		stateByRoot                 map[[fieldparams.RootLength]byte]state.BeaconState
    75→	}
    76→
    77→	rodataColumnsCommitmentVerifier func([]blocks.RODataColumn) error
    78→)
    79→
    80→var _ DataColumnsVerifier = &RODataColumnsVerifier{}
    81→
    82→// VerifiedRODataColumns "upgrades" wrapped RODataColumns to VerifiedRODataColumns.
    83→// If any of the verifications ran against the data columns failed, or some required verifications
    84→// were not run, an error will be returned.
    85→func (dv *RODataColumnsVerifier) VerifiedRODataColumns() ([]blocks.VerifiedRODataColumn, error) {
    86→	if !dv.results.allSatisfied() {
    87→		return nil, dv.results.errors(errColumnsInvalid)
    88→	}
    89→
    90→	verifiedRODataColumns := make([]blocks.VerifiedRODataColumn, 0, len(dv.dataColumns))
    91→	for _, dataColumn := range dv.dataColumns {
    92→		verifiedRODataColumn := blocks.NewVerifiedRODataColumn(dataColumn)
    93→		verifiedRODataColumns = append(verifiedRODataColumns, verifiedRODataColumn)
    94→	}
    95→
    96→	return verifiedRODataColumns, nil
    97→}
    98→
    99→// SatisfyRequirement allows the caller to assert that a requirement has been satisfied.
   100→// This gives us a way to tick the box for a requirement where the usual method would be impractical.
   101→// For example, when batch syncing, forkchoice is only updated at the end of the batch. So the checks that use
   102→// forkchoice, like descends from finalized or parent seen, would necessarily fail. Allowing the caller to
   103→// assert the requirement has been satisfied ensures we have an easy way to audit which piece of code is satisfying
   104→// a requirement outside of this package.
   105→func (dv *RODataColumnsVerifier) SatisfyRequirement(req Requirement) {
   106→	dv.recordResult(req, nil)
   107→}
   108→
   109→func (dv *RODataColumnsVerifier) recordResult(req Requirement, err *error) {
   110→	if err == nil || *err == nil {
   111→		dv.results.record(req, nil)
   112→		return
   113→	}
   114→	dv.results.record(req, *err)
   115→}
   116→
   117→func (dv *RODataColumnsVerifier) ValidFields() (err error) {
   118→	if ok, err := dv.results.cached(RequireValidFields); ok {
   119→		return err
   120→	}
   121→
   122→	defer dv.recordResult(RequireValidFields, &err)
   123→
   124→	for _, dataColumn := range dv.dataColumns {
   125→		if err := peerdas.VerifyDataColumnSidecar(dataColumn); err != nil {
   126→			return columnErrBuilder(errors.Wrap(err, "verify data column sidecar"))
   127→		}
   128→	}
   129→
   130→	return nil
   131→}
   132→
   133→func (dv *RODataColumnsVerifier) CorrectSubnet(dataColumnSidecarSubTopic string, expectedTopics []string) (err error) {
   134→	if ok, err := dv.results.cached(RequireCorrectSubnet); ok {
   135→		return err
   136→	}
   137→
   138→	defer dv.recordResult(RequireCorrectSubnet, &err)
   139→
   140→	if len(expectedTopics) != len(dv.dataColumns) {
   141→		return columnErrBuilder(errBadTopicLength)
   142→	}
   143→
   144→	for i := range dv.dataColumns {
   145→		// We add a trailing slash to avoid, for example,
   146→		// an actual topic /eth2/9dc47cc6/data_column_sidecar_1
   147→		// to match with /eth2/9dc47cc6/data_column_sidecar_120
   148→		expectedTopic := expectedTopics[i] + "/"
   149→
   150→		actualSubnet := peerdas.ComputeSubnetForDataColumnSidecar(dv.dataColumns[i].Index)
   151→		actualSubTopic := fmt.Sprintf(dataColumnSidecarSubTopic, actualSubnet)
   152→
   153→		if !strings.Contains(expectedTopic, actualSubTopic) {
   154→			return columnErrBuilder(errBadTopic)
   155→		}
   156→	}
   157→
   158→	return nil
   159→}
   160→
   161→func (dv *RODataColumnsVerifier) NotFromFutureSlot() (err error) {
   162→	if ok, err := dv.results.cached(RequireNotFromFutureSlot); ok {
   163→		return err
   164→	}
   165→
   166→	defer dv.recordResult(RequireNotFromFutureSlot, &err)
   167→
   168→	// Retrieve the current slot.
   169→	currentSlot := dv.clock.CurrentSlot()
   170→
   171→	// Get the current time.
   172→	now := dv.clock.Now()
   173→
   174→	// Retrieve the maximum gossip clock disparity.
   175→	maximumGossipClockDisparity := params.BeaconConfig().MaximumGossipClockDisparityDuration()
   176→
   177→	for _, dataColumn := range dv.dataColumns {
   178→		// Extract the data column slot.
   179→		dataColumnSlot := dataColumn.Slot()
   180→
   181→		// Skip if the data column slot is the same as the current slot.
   182→		if currentSlot == dataColumnSlot {
   183→			continue
   184→		}
   185→
   186→		// earliestStart represents the time the slot starts, lowered by MAXIMUM_GOSSIP_CLOCK_DISPARITY.
   187→		// We lower the time by MAXIMUM_GOSSIP_CLOCK_DISPARITY in case system time is running slightly behind real time.
   188→		earliestStart, err := dv.clock.SlotStart(dataColumnSlot)
   189→		if err != nil {
   190→			return columnErrBuilder(errors.Wrap(err, "failed to determine slot start time from clock waiter"))
   191→		}
   192→		earliestStart = earliestStart.Add(-maximumGossipClockDisparity)
   193→
   194→		// If the system time is still before earliestStart, we consider the column from a future slot and return an error.
   195→		if now.Before(earliestStart) {
   196→			return columnErrBuilder(errFromFutureSlot)
   197→		}
   198→	}
   199→
   200→	return nil
   201→}
   202→
   203→func (dv *RODataColumnsVerifier) SlotAboveFinalized() (err error) {
   204→	if ok, err := dv.results.cached(RequireSlotAboveFinalized); ok {
   205→		return err
   206→	}
   207→
   208→	defer dv.recordResult(RequireSlotAboveFinalized, &err)
   209→
   210→	// Retrieve the finalized checkpoint.
   211→	finalizedCheckpoint := dv.fc.FinalizedCheckpoint()
   212→
   213→	// Compute the first slot of the finalized checkpoint epoch.
   214→	startSlot, err := slots.EpochStart(finalizedCheckpoint.Epoch)
   215→	if err != nil {
   216→		return columnErrBuilder(errors.Wrap(err, "epoch start"))
   217→	}
   218→
   219→	for _, dataColumn := range dv.dataColumns {
   220→		// Check if the data column slot is after first slot of the epoch corresponding to the finalized checkpoint.
   221→		if dataColumn.Slot() <= startSlot {
   222→			return columnErrBuilder(errSlotNotAfterFinalized)
   223→		}
   224→	}
   225→
   226→	return nil
   227→}
   228→
   229→func (dv *RODataColumnsVerifier) ValidProposerSignature(ctx context.Context) (err error) {
   230→	if ok, err := dv.results.cached(RequireValidProposerSignature); ok {
   231→		return err
   232→	}
   233→
   234→	defer dv.recordResult(RequireValidProposerSignature, &err)
   235→
   236→	for _, dataColumn := range dv.dataColumns {
   237→		// Extract the signature data from the data column.
   238→		signatureData := columnToSignatureData(dataColumn)
   239→
   240→		// Get logging fields.
   241→		fields := logging.DataColumnFields(dataColumn)
   242→		log := log.WithFields(fields)
   243→
   244→		// First check if there is a cached verification that can be reused.
   245→		seen, err := dv.sc.SignatureVerified(signatureData)
   246→		if err != nil {
   247→			log.WithError(err).Debug("Reusing failed proposer signature validation from cache")
   248→
   249→			columnVerificationProposerSignatureCache.WithLabelValues("hit-invalid").Inc()
   250→			return columnErrBuilder(ErrInvalidProposerSignature)
   251→		}
   252→
   253→		// If yes, we can skip the full verification.
   254→		if seen {
   255→			columnVerificationProposerSignatureCache.WithLabelValues("hit-valid").Inc()
   256→			continue
   257→		}
   258→
   259→		columnVerificationProposerSignatureCache.WithLabelValues("miss").Inc()
   260→
   261→		// Retrieve the parent state.
   262→		parentState, err := dv.parentState(ctx, dataColumn)
   263→		if err != nil {
   264→			return columnErrBuilder(errors.Wrap(err, "parent state"))
   265→		}
   266→
   267→		// Full verification, which will subsequently be cached for anything sharing the signature cache.
   268→		if err = dv.sc.VerifySignature(signatureData, parentState); err != nil {
   269→			return columnErrBuilder(errors.Wrap(err, "verify signature"))
   270→		}
   271→	}
   272→
   273→	return nil
   274→}
   275→
   276→func (dv *RODataColumnsVerifier) SidecarParentSeen(parentSeen func([fieldparams.RootLength]byte) bool) (err error) {
   277→	if ok, err := dv.results.cached(RequireSidecarParentSeen); ok {
   278→		return err
   279→	}
   280→
   281→	defer dv.recordResult(RequireSidecarParentSeen, &err)
   282→
   283→	for _, dataColumn := range dv.dataColumns {
   284→		// Skip if the parent root has been seen.
   285→		parentRoot := dataColumn.ParentRoot()
   286→		if parentSeen != nil && parentSeen(parentRoot) {
   287→			continue
   288→		}
   289→
   290→		if !dv.fc.HasNode(parentRoot) {
   291→			return columnErrBuilder(errSidecarParentNotSeen)
   292→		}
   293→	}
   294→
   295→	return nil
   296→}
   297→
   298→func (dv *RODataColumnsVerifier) SidecarParentValid(badParent func([fieldparams.RootLength]byte) bool) (err error) {
   299→	if ok, err := dv.results.cached(RequireSidecarParentValid); ok {
   300→		return err
   301→	}
   302→
   303→	defer dv.recordResult(RequireSidecarParentValid, &err)
   304→
   305→	for _, dataColumn := range dv.dataColumns {
   306→		if badParent != nil && badParent(dataColumn.ParentRoot()) {
   307→			return columnErrBuilder(errSidecarParentInvalid)
   308→		}
   309→	}
   310→
   311→	return nil
   312→}
   313→
   314→func (dv *RODataColumnsVerifier) SidecarParentSlotLower() (err error) {
   315→	if ok, err := dv.results.cached(RequireSidecarParentSlotLower); ok {
   316→		return err
   317→	}
   318→
   319→	defer dv.recordResult(RequireSidecarParentSlotLower, &err)
   320→
   321→	for _, dataColumn := range dv.dataColumns {
   322→		// Compute the slot of the parent block.
   323→		parentSlot, err := dv.fc.Slot(dataColumn.ParentRoot())
   324→		if err != nil {
   325→			return columnErrBuilder(errors.Wrap(err, "slot"))
   326→		}
   327→
   328→		// Check if the data column slot is after the parent slot.
   329→		if parentSlot >= dataColumn.Slot() {
   330→			return columnErrBuilder(errSlotNotAfterParent)
   331→		}
   332→	}
   333→
   334→	return nil
   335→}
   336→
   337→func (dv *RODataColumnsVerifier) SidecarDescendsFromFinalized() (err error) {
   338→	if ok, err := dv.results.cached(RequireSidecarDescendsFromFinalized); ok {
   339→		return err
   340→	}
   341→
   342→	defer dv.recordResult(RequireSidecarDescendsFromFinalized, &err)
   343→
   344→	for _, dataColumn := range dv.dataColumns {
   345→		// Extract the root of the parent block corresponding to the data column.
   346→		parentRoot := dataColumn.ParentRoot()
   347→
   348→		if !dv.fc.HasNode(parentRoot) {
   349→			return columnErrBuilder(errSidecarNotFinalizedDescendent)
   350→		}
   351→	}
   352→
   353→	return nil
   354→}
   355→
   356→func (dv *RODataColumnsVerifier) SidecarInclusionProven() (err error) {
   357→	if ok, err := dv.results.cached(RequireSidecarInclusionProven); ok {
   358→		return err
   359→	}
   360→
   361→	defer dv.recordResult(RequireSidecarInclusionProven, &err)
   362→
   363→	startTime := time.Now()
   364→
   365→	for _, dataColumn := range dv.dataColumns {
   366→		k, keyErr := inclusionProofKey(dataColumn)
   367→		if keyErr == nil {
   368→			if _, ok := dv.ic.Get(k); ok {
   369→				continue
   370→			}
   371→		} else {
   372→			log.WithError(keyErr).Error("Failed to get inclusion proof key")
   373→		}
   374→
   375→		if err = peerdas.VerifyDataColumnSidecarInclusionProof(dataColumn); err != nil {
   376→			return columnErrBuilder(ErrSidecarInclusionProofInvalid)
   377→		}
   378→
   379→		if keyErr == nil {
   380→			dv.ic.Add(k, struct{}{})
   381→		}
   382→	}
   383→
   384→	dataColumnSidecarInclusionProofVerificationHistogram.Observe(float64(time.Since(startTime).Milliseconds()))
   385→
   386→	return nil
   387→}
   388→
   389→func (dv *RODataColumnsVerifier) SidecarKzgProofVerified() (err error) {
   390→	if ok, err := dv.results.cached(RequireSidecarKzgProofVerified); ok {
   391→		return err
   392→	}
   393→
   394→	defer dv.recordResult(RequireSidecarKzgProofVerified, &err)
   395→
   396→	startTime := time.Now()
   397→
   398→	err = dv.verifyDataColumnsCommitment(dv.dataColumns)
   399→	if err != nil {
   400→		return columnErrBuilder(errors.Wrap(err, "verify data column commitment"))
   401→	}
   402→
   403→	dataColumnBatchKZGVerificationHistogram.Observe(float64(time.Since(startTime).Milliseconds()))
   404→	return nil
   405→}
   406→
   407→func (dv *RODataColumnsVerifier) SidecarProposerExpected(ctx context.Context) (err error) {
   408→	if ok, err := dv.results.cached(RequireSidecarProposerExpected); ok {
   409→		return err
   410→	}
   411→
   412→	defer dv.recordResult(RequireSidecarProposerExpected, &err)
   413→
   414→	type slotParentRoot struct {
   415→		slot       primitives.Slot
   416→		parentRoot [fieldparams.RootLength]byte
   417→	}
   418→
   419→	targetRootBySlotParentRoot := make(map[slotParentRoot][fieldparams.RootLength]byte)
   420→
   421→	var targetRootFromCache = func(slot primitives.Slot, parentRoot [fieldparams.RootLength]byte) ([fieldparams.RootLength]byte, error) {
   422→		// Use cached values if available.
   423→		slotParentRoot := slotParentRoot{slot: slot, parentRoot: parentRoot}
   424→		if root, ok := targetRootBySlotParentRoot[slotParentRoot]; ok {
   425→			return root, nil
   426→		}
   427→
   428→		// Compute the epoch of the data column slot.
   429→		dataColumnEpoch := slots.ToEpoch(slot)
   430→		if dataColumnEpoch > 0 {
   431→			dataColumnEpoch = dataColumnEpoch - 1
   432→		}
   433→
   434→		// Compute the target root for the epoch.
   435→		targetRoot, err := dv.fc.TargetRootForEpoch(parentRoot, dataColumnEpoch)
   436→		if err != nil {
   437→			return [fieldparams.RootLength]byte{}, columnErrBuilder(errors.Wrap(err, "target root from epoch"))
   438→		}
   439→
   440→		// Store the target root in the cache.
   441→		targetRootBySlotParentRoot[slotParentRoot] = targetRoot
   442→
   443→		return targetRoot, nil
   444→	}
   445→
   446→	for _, dataColumn := range dv.dataColumns {
   447→		// Extract the slot of the data column.
   448→		dataColumnSlot := dataColumn.Slot()
   449→
   450→		// Extract the root of the parent block corresponding to the data column.
   451→		parentRoot := dataColumn.ParentRoot()
   452→
   453→		// Compute the target root for the data column.
   454→		targetRoot, err := targetRootFromCache(dataColumnSlot, parentRoot)
   455→		if err != nil {
   456→			return columnErrBuilder(errors.Wrap(err, "target root"))
   457→		}
   458→
   459→		// Compute the epoch of the data column slot.
   460→		dataColumnEpoch := slots.ToEpoch(dataColumnSlot)
   461→		if dataColumnEpoch > 0 {
   462→			dataColumnEpoch = dataColumnEpoch - 1
   463→		}
   464→
   465→		// Create a checkpoint for the target root.
   466→		checkpoint := &forkchoicetypes.Checkpoint{Root: targetRoot, Epoch: dataColumnEpoch}
   467→
   468→		// Try to extract the proposer index from the data column in the cache.
   469→		idx, cached := dv.pc.Proposer(checkpoint, dataColumnSlot)
   470→
   471→		if !cached {
   472→			// Retrieve the parent state.
   473→			parentState, err := dv.parentState(ctx, dataColumn)
   474→			if err != nil {
   475→				return columnErrBuilder(errors.Wrap(err, "parent state"))
   476→			}
   477→
   478→			idx, err = dv.pc.ComputeProposer(ctx, parentRoot, dataColumnSlot, parentState)
   479→			if err != nil {
   480→				return columnErrBuilder(errors.Wrap(err, "compute proposer"))
   481→			}
   482→		}
   483→
   484→		if idx != dataColumn.ProposerIndex() {
   485→			return columnErrBuilder(errSidecarUnexpectedProposer)
   486→		}
   487→	}
   488→
   489→	return nil
   490→}
   491→
   492→// parentState retrieves the parent state of the data column from the cache if possible, else retrieves it from the state by rooter.
   493→func (dv *RODataColumnsVerifier) parentState(ctx context.Context, dataColumn blocks.RODataColumn) (state.BeaconState, error) {
   494→	parentRoot := dataColumn.ParentRoot()
   495→
   496→	// If the parent root is already in the cache, return it.
   497→	if st, ok := dv.stateByRoot[parentRoot]; ok {
   498→		return st, nil
   499→	}
   500→
   501→	// Retrieve the parent state from the state by rooter.
   502→	st, err := dv.sr.StateByRoot(ctx, parentRoot)
   503→	if err != nil {
   504→		return nil, errors.Wrap(err, "state by root")
   505→	}
   506→
   507→	// Store the parent state in the cache.
   508→	dv.stateByRoot[parentRoot] = st
   509→
   510→	return st, nil
   511→}
   512→
   513→func columnToSignatureData(d blocks.RODataColumn) signatureData {
   514→	return signatureData{
   515→		Root:      d.BlockRoot(),
   516→		Parent:    d.ParentRoot(),
   517→		Signature: bytesutil.ToBytes96(d.SignedBlockHeader.Signature),
   518→		Proposer:  d.ProposerIndex(),
   519→		Slot:      d.Slot(),
   520→	}
   521→}
   522→
   523→func columnErrBuilder(baseErr error) error {
   524→	return errors.Wrap(baseErr, errColumnsInvalid.Error())
   525→}
   526→
   527→func inclusionProofKey(c blocks.RODataColumn) ([160]byte, error) {
   528→	var key [160]byte
   529→	if len(c.KzgCommitmentsInclusionProof) != 4 {
   530→		// This should be already enforced by ssz unmarshaling; still check so we don't panic on array bounds.
   531→		return key, columnErrBuilder(ErrSidecarInclusionProofInvalid)
   532→	}
   533→
   534→	root, err := c.SignedBlockHeader.HashTreeRoot()
   535→	if err != nil {
   536→		return [160]byte{}, columnErrBuilder(errors.Wrap(err, "hash tree root"))
   537→	}
   538→
   539→	for i := range c.KzgCommitmentsInclusionProof {
   540→		if copy(key[32*i:32*i+32], c.KzgCommitmentsInclusionProof[i]) != 32 {
   541→			return key, columnErrBuilder(ErrSidecarInclusionProofInvalid)
   542→		}
   543→	}
   544→
   545→	copy(key[128:], root[:])
   546→	return key, nil
   547→}
   548→

